-- Shared, stable word catalog for the current interactive IPA chart.
-- Existing sound IDs and approved audio rows are preserved; this is additive.
create table if not exists public.ipa_chart_words (
  id uuid primary key default gen_random_uuid(),
  spelling text not null check (length(btrim(spelling)) between 1 and 80),
  normalized_spelling text not null unique,
  is_active boolean not null default true,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.ipa_chart_word_pronunciations (
  id uuid primary key default gen_random_uuid(),
  word_id uuid not null references public.ipa_chart_words(id) on delete cascade,
  accent text not null check (accent in ('uk', 'us')),
  sound_id text not null,
  ipa text not null check (length(btrim(ipa)) between 1 and 120),
  spelling_markup text not null check (length(btrim(spelling_markup)) between 1 and 80),
  sort_order integer not null default 0,
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (word_id, accent, sound_id)
);

create unique index if not exists ipa_chart_word_pronunciations_one_default_idx
  on public.ipa_chart_word_pronunciations (word_id, accent) where is_default;
create index if not exists ipa_chart_word_pronunciations_sound_idx
  on public.ipa_chart_word_pronunciations (accent, sound_id, sort_order);

alter table public.ipa_chart_audio_assets
  add column if not exists word_id uuid references public.ipa_chart_words(id) on delete set null;
create index if not exists ipa_chart_audio_assets_word_accent_idx
  on public.ipa_chart_audio_assets (word_id, accent) where asset_type = 'word';

alter table public.ipa_chart_words enable row level security;
alter table public.ipa_chart_word_pronunciations enable row level security;
revoke all on public.ipa_chart_words from anon, authenticated;
revoke all on public.ipa_chart_word_pronunciations from anon, authenticated;
grant select on public.ipa_chart_words to anon, authenticated;
grant select on public.ipa_chart_word_pronunciations to anon, authenticated;
grant all on public.ipa_chart_words to service_role;
grant all on public.ipa_chart_word_pronunciations to service_role;

drop policy if exists "Public can read active IPA chart words" on public.ipa_chart_words;
create policy "Public can read active IPA chart words"
  on public.ipa_chart_words for select to anon, authenticated using (is_active);
drop policy if exists "Platform admins manage IPA chart words" on public.ipa_chart_words;
create policy "Platform admins manage IPA chart words"
  on public.ipa_chart_words for all to authenticated
  using ((select role = 'ADMIN' from public.profiles where id = auth.uid()))
  with check ((select role = 'ADMIN' from public.profiles where id = auth.uid()));

drop policy if exists "Public can read IPA chart word pronunciations" on public.ipa_chart_word_pronunciations;
create policy "Public can read IPA chart word pronunciations"
  on public.ipa_chart_word_pronunciations for select to anon, authenticated
  using (exists (select 1 from public.ipa_chart_words w where w.id = word_id and w.is_active));
drop policy if exists "Platform admins manage IPA chart word pronunciations" on public.ipa_chart_word_pronunciations;
create policy "Platform admins manage IPA chart word pronunciations"
  on public.ipa_chart_word_pronunciations for all to authenticated
  using ((select role = 'ADMIN' from public.profiles where id = auth.uid()))
  with check ((select role = 'ADMIN' from public.profiles where id = auth.uid()));

