), words as (
  insert into public.ipa_chart_words (spelling, normalized_spelling)
  select distinct on (lower(btrim(spelling))) spelling, lower(btrim(spelling))
  from seed order by lower(btrim(spelling)), spelling
  on conflict (normalized_spelling) do update set updated_at = public.ipa_chart_words.updated_at
  returning id, normalized_spelling
)
insert into public.ipa_chart_word_pronunciations
  (word_id, accent, sound_id, ipa, spelling_markup, sort_order, is_default)
select w.id, s.accent, s.sound_id, s.ipa, s.spelling_markup, s.sort_order, s.is_default
from seed s
join words w on w.normalized_spelling = lower(btrim(s.spelling))
on conflict (word_id, accent, sound_id) do nothing;

-- Link existing word recordings without changing their review status or URLs.
update public.ipa_chart_audio_assets a
set word_id = w.id
from public.ipa_chart_words w
where a.asset_type = 'word'
  and a.word_id is null
  and lower(btrim(a.word)) = w.normalized_spelling;
